$ErrorActionPreference='SilentlyContinue'
$rows=@()
$configs=Get-ChildItem -Path 'C:\Users\Xxkan' -Filter config -File -Recurse -ErrorAction SilentlyContinue |
  Where-Object { $_.Directory.Name -eq '.git' -and (Select-String -Path $_.FullName -Pattern 'fengie/mhw-mods' -Quiet -ErrorAction SilentlyContinue) }
foreach($cfg in $configs){
  $repo=$cfg.Directory.Parent.FullName
  Push-Location $repo
  try{
    $current=(& git branch --show-current 2>$null | Out-String).Trim()
    $head=(& git rev-parse HEAD 2>$null | Out-String).Trim()
    $dirty=((& git status --porcelain=v1 2>$null | Out-String).Trim().Length -gt 0)
    $worktrees=(& git worktree list --porcelain 2>$null | Out-String).Trim()
    $rows += [ordered]@{repo=$repo;current=$current;head=$head;dirty=$dirty;worktrees=$worktrees}
  } finally {Pop-Location}
}
$rows|ConvertTo-Json -Depth 5
